export interface TTSConfig {
    /** Model directory or repository identifier. Defaults to "kokoro". */
    modelId?: string;
    /** Local asset base path containing the model files. Defaults to "/models". */
    localModelPath?: string;
    /** Whether to allow fetching remote models from Hugging Face. Defaults to false. */
    allowRemoteFallback?: boolean;
    /** Execution device. Defaults to "auto" (WebGPU with WASM fallback). */
    device?: "auto" | "webgpu" | "wasm" | "cpu";
    /** Quantization data type. Defaults to "fp32" for WebGPU. */
    dtype?: "fp32" | "fp16" | "q8" | "q4" | "q4f16";
    /** Progress callback during session initialization. */
    progressCallback?: (progress: TTSProgress) => void;
    /** In-memory LRU cache to avoid re-synthesizing repeated sentences. Defaults to true. */
    cacheAudio?: boolean;
    /** Maximum entries to retain in the audio cache. Defaults to 128. */
    maxCacheSize?: number;
}

