import { Scene, Color, hex, SDFText, Circle, Arrow, CENTER } from "retiam";
import { TTS, speak, Subtitles, TTSNarrationComponent } from "retiam/tts";

export class NondeterminismMasterclassScene extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 48]);
        this.clearColor(new Color(0.04, 0.05, 0.08, 1.0));

        // 1. Audio Mixing Bed: Ambient Rhodes Jazz Chords (-24 dB)
        this.audio.setMasterVolume(1.0);
        this.audio.setVoiceoverVolume(1.0);

        const rhodesBed = createRhodesAmbientBed(this.audio);
        this.audio.timeline.addClip(rhodesBed, 0, this.audio.bgmGain, {
            volume: 0.05, // Ducked -24 dB relative to speech
            loop: true
        });

        // 2. Closed Captions HUD
        const subtitles = new Subtitles({ fontSize: 0.50, showBackdrop: true });
        subtitles.setBottomOffset(-9.6);
        this.add(subtitles);

        // 3. Mathematical Automata State (Centered text with anchor: CENTER)
        const q0 = new Circle(1.5, { stroke: hex("#F59E0B"), stroke_width: 0.06 });
        q0.transform.position.set([-8.5, -0.8, 0]);
        this.add(q0);

        const q0Label = new SDFText("q0", { fontSize: 0.60, anchor: CENTER });
        q0Label.transform.position.set([-8.5, -0.8, 0.01]);
        this.add(q0Label);

        // 4. Beat 1: The Hook & Rhetorical Question (Contemplative upward inflection)
        await speak(this, "What if a machine could explore multiple futures... simultaneously?", {
            provider: "msedge",
            voice: "en-US-AndrewNeural",
            speed: 0.96,       // -4% speech rate for pedagogical weight
            pitch: "+0Hz",
            volume: 1.0,       // Full 100% studio volume
            subtitles,
            duckingRatio: 0.20 // Ducks BGM by 80% during speech
        });

        // Programmatic Breathing Pause: 1.6s silence for concept to settle
        await this.wait(1600);

        // 5. Beat 2: Theorem Statement & Grounding Resolution
        await speak(this, "Yet, through the elegance of the Subset Construction theorem, any nondeterministic machine can be folded back into an equivalent deterministic universe.", {
            provider: "msedge",
            voice: "en-US-AndrewNeural",
            speed: 0.96,
            pitch: "+0Hz",
            volume: 1.0,
            subtitles,
            duckingRatio: 0.20
        });

        await this.wait(1800);

        // 6. Mastering: Soft 1.5s Fade-Out of Ambient Rhodes Bed
        this.audio.stopBGM(1500);
    }
}
